package com.lightweight.{{SLUG_PKG}}

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool

/**
 * Thin SoundPool wrapper for tiny synthesized WAVs in res/raw.
 *
 * Sounds are generated by tools/gen_sounds.py and committed under
 * app/src/main/res/raw/. Once they exist, uncomment the load()/play() lines and
 * reference them as R.raw.s_xxx. Call release() from GameView.surfaceDestroyed.
 */
class Sound(ctx: Context) {

    private val pool = SoundPool.Builder()
        .setMaxStreams(4)
        .setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_GAME)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build()
        )
        .build()

    // TODO (per game): load the sounds this game uses, e.g.
    //   private val moveId = pool.load(ctx, R.raw.s_move, 1)
    //   fun move() { pool.play(moveId, 0.6f, 0.6f, 1, 0, 1f) }

    fun release() {
        pool.release()
    }
}
